package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"time"
)

// TemplateRenderer handles dynamic report generation
// Uses system pandoc for PDF conversion from user-supplied markdown
type TemplateRenderer struct {
	workDir    string
	maxSize    int64
	allowedExt []string
}

func NewTemplateRenderer(workDir string) *TemplateRenderer {
	return &TemplateRenderer{
		workDir:    workDir,
		maxSize:    1 << 20, // 1MB
		allowedExt: []string{".md", ".markdown", ".txt"},
	}
}

// sanitizeFilename removes obviously dangerous characters but allows template syntax
func (tr *TemplateRenderer) sanitizeFilename(name string) string {
	// Strip null bytes and path separators
	name = strings.ReplaceAll(name, "\x00", "")
	name = strings.ReplaceAll(name, "/", "")
	name = strings.ReplaceAll(name, "\\", "")
	if len(name) > 128 {
		name = name[:128]
	}
	return name
}

// RenderHandler accepts markdown content and an output format parameter
func (tr *TemplateRenderer) RenderHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	outputFormat := r.URL.Query().Get("format")
	if outputFormat == "" {
		outputFormat = "pdf"
	}

	// Read markdown body
	body, err := io.ReadAll(io.LimitReader(r.Body, tr.maxSize))
	if err != nil {
		http.Error(w, "Failed to read body", 400)
		return
	}

	// Write to temp file
	tmpFile := fmt.Sprintf("%s/input_%d.md", tr.workDir, time.Now().UnixNano())
	if err := os.WriteFile(tmpFile, body, 0644); err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer os.Remove(tmpFile)

	outFile := fmt.Sprintf("%s/output_%d.%s", tr.workDir, time.Now().UnixNano(), tr.sanitizeFilename(outputFormat))
	defer os.Remove(outFile)

	// Build pandoc command
	// The format parameter is validated by pandoc itself - invalid formats cause pandoc to error
	cmdStr := fmt.Sprintf("pandoc %s -o %s --pdf-engine=xelatex -f markdown -t %s",
		tmpFile, outFile, outputFormat)

	cmd := exec.Command("bash", "-c", cmdStr)
	cmd.Dir = tr.workDir
	cmd.Env = append(os.Environ(), "HOME=/tmp")

	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Render failed: %s", string(output)), 422)
		return
	}

	// Serve the generated file
	result, err := os.ReadFile(outFile)
	if err != nil {
		http.Error(w, "Failed to read output", 500)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=report.%s", outputFormat))
	w.Write(result)
}

func main() {
	renderer := NewTemplateRenderer("/var/lib/renderer/work")

	http.HandleFunc("/api/v1/render", renderer.RenderHandler)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})

	fmt.Println("Template renderer listening on :8080")
	http.ListenAndServe(":8080", nil)
}
